            "niv": "So he raised up their sons in their place, and these were the ones Joshua circumcised. They were still 353 uncircumcised because they had not been circumcised on the way.",
            "esv": "So it was their children, whom he raised up in their place, that Joshua circumcised. For they were uncircumcised, because they had not been circumcised on the way."
